parameters.jsCode:
// 1. On récupère le JSON généré par l'IA
let iaData = $('AI Agent').first().json;

// Nettoyage classique
if (iaData.output && typeof iaData.output === 'string') {
    try {
        let cleanText = iaData.output.replace(/```json/gi, '').replace(/```/g, '').trim();
        iaData = JSON.parse(cleanText);
    } catch (e) {}
} else if (iaData.output) {
    iaData = iaData.output;
}

// ====================================================================
// LE PLAN B INFAILLIBLE : On extrait les liens en force sans l'IA
// ====================================================================

// On va chercher le code HTML du mail dans ton nœud "Get a message"
const mailHtml = $('Get a message').first().json.html || $('Get a message').first().json.textAsHtml || $('Get a message').first().json.snippet || "";

// On utilise une formule (Regex) pour aspirer strictement les liens Drive et Google Photos
const regexLiens = /https?:\/\/(?:drive\.google\.com|photos\.app\.goo\.gl)[^\s"'>]+/gi;
const liensTrouves = mailHtml.match(regexLiens) || [];

// Si on a trouvé des liens, on supprime les doublons et on force l'écriture dans "joints"
if (liensTrouves.length > 0) {
    const liensUniques = [...new Set(liensTrouves)];
    iaData.joints = liensUniques.join(" | "); 
}
// ====================================================================
// Le chemin mail impose sa provenance : les scrapers ont la leur.
iaData.provenance = 'E-mail';
// ====================================================================

let elementsPourLaBoucle = [];
let aTrouveDesFichiers = false;

// 2. On boucle sur les vrais fichiers physiques (les JPEG, etc.)
for (const email of $input.all()) { 
    if (email.binary) {
        for (const key of Object.keys(email.binary)) {
            if (key.startsWith('attachment_')) {
                aTrouveDesFichiers = true;

                elementsPourLaBoucle.push({
                    json: { ...iaData },
                    binary: {
                        data: email.binary[key] 
                    }
                });
            }
        }
    }
}

// 3. Si aucun vrai fichier, on garde le prospect quand même
if (!aTrouveDesFichiers) {
    elementsPourLaBoucle.push({
        json: { ...iaData }
    });
}

return elementsPourLaBoucle;

const items = $input.all();
if (items.length === 0) return [];

// 1. On prend le premier élément comme base
const prospectUnique = { ...items[0].json };

// 2. On prépare une liste vide pour stocker tous les liens
let tousLesLiens = [];

// 3. On boucle sur chaque ligne pour récupérer et découper les liens
items.forEach(item => {
    let liensBruts = item.json.liens_fichiers || "";

    // Si la chaîne commence par "=" (parfois ajouté par n8n), on l'enlève
    if (typeof liensBruts === 'string' && liensBruts.startsWith('=')) {
        liensBruts = liensBruts.slice(1);
    }

    // On sépare les liens (qui sont collés avec des "|") et on nettoie les espaces
    if (typeof liensBruts === 'string') {
        let liensSepares = liensBruts.split('|').map(l => l.trim()).filter(l => l !== '');
        tousLesLiens = tousLesLiens.concat(liensSepares);
    } else if (Array.isArray(liensBruts)) {
        tousLesLiens = tousLesLiens.concat(liensBruts);
    }
});

// 4. LA MAGIE : On supprime tous les doublons stricts
let liensUniques = [...new Set(tousLesLiens)];

// 5. On rassemble tout dans une seule belle chaîne de caractères propre
prospectUnique.liens_fichiers = liensUniques.join("\n"); 
// (J'ai mis "\n" pour faire des sauts de ligne sur Notion, c'est plus lisible ! 
// Si tu préfères les barres, remplace "\n" par " | ")

// 6. On renvoie un SEUL et unique item parfait
return [{ json: prospectUnique }];

const body = $input.item.json.body || $input.item.json;

// On restaure les vrais retours à la ligne
const contactText = (body.contactClean || "").replace(/##BR##/g, '\n');
const infoProjetText = (body.infoProjetClean || "").replace(/##BR##/g, '\n');
const typeProjetText = (body.typeProjetClean || "").replace(/##BR##/g, '\n');
const adresseText = (body.adresseClean || "").replace(/##BR##/g, '\n');

const getValue = (text, key) => {
  const regex = new RegExp(`${key}\\s*[:]*\\s*(.*?)(?=\\n|$)`, 'i');
  const match = text.match(regex);
  return match ? match[1].trim() : "";
};

const nom = getValue(contactText, 'name');
const email = getValue(contactText, 'email');
const telephone = getValue(contactText, 'phone');
const entreprise = getValue(contactText, 'companyName');

const localisation = adresseText.trim() || 
                     getValue(infoProjetText, 'localisation') || 
                     getValue(infoProjetText, 'adresse') || 
                     "Non spécifiée";

// 🔥 Sécurité : Si le type de projet est vide, on met "Projet Houzz" pour éviter le crash de Notion
const typeProjet = typeProjetText.trim() || getValue(infoProjetText, 'type de projet') || "Projet Houzz";

const liensFichiers = getValue(infoProjetText, 'joints') || "";
const description = infoProjetText; 
const urlPlateforme = body.activeTabUrl || "";
const provenance = "Houzz";

// On génère la structure en double (avec et sans espaces) pour valider toutes tes formules
const dataStructure = {
  nom: nom,
  email: email,
  telephone: telephone,
  entreprise: entreprise,
  'URL plateforme': urlPlateforme,
  localisation: localisation,
  description: description,
  provenance: provenance,
  'Type de projet': typeProjet, // ✨ Pour ta formule dans Variables Normalisées1
  type_projet: typeProjet,      // ✨ Sécurité pour le titre de ton Notion
  liens_fichiers: liensFichiers
};

return {
  json: {
    ...dataStructure,
    body: dataStructure,
    output: dataStructure
  }
};

const cleanItems = [];

for (const item of $input.all()) {
  const newJson = JSON.parse(JSON.stringify(item.json));

  // On efface les balises texte des images
  if (newJson.text) {
      newJson.text = newJson.text.replace(/\[image:.*?\]/gi, '');
  }

  // 🔥 ICI : On déplace les fichiers dans une propriété "cachée" dans le JSON
  // L'IA ne lira pas ce contenu, mais les nœuds suivants pourront le récupérer
  cleanItems.push({ 
    json: {
        ...newJson,
        _tempBinary: item.binary // On stocke les fichiers ici
    }
    // On ne met PAS "binary: item.binary" ici, pour cacher les fichiers à l'IA
  });
}

return cleanItems;

