parameters.jsCode:
// Sort l'adresse de l'expediteur, exploitable sans IA.
const out = [];
for (const item of $input.all()) {
  const j = { ...item.json };
  const brut = j.headers?.from || j.from || '';
  const m = String(brut).match(/<([^>]+)>/);
  j.email_expediteur = (m ? m[1] : String(brut)).trim().toLowerCase();
  out.push({ json: j });
}
return out;

// Le script Google envoie { messageId }. Une entree vide n'alimente rien :
// la chaine ne tourne pas, et aucune execution inutile n'est creee.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const corps = j.body || j;
  const id = String(corps.messageId || corps.message_id || corps.id || '').trim();
  if (!id) continue;
  out.push({ json: { id, messageId: id, origine: 'bouton-gmail' } });
}
return out;
